solution.solution.cpp:
#include <cctype>
#include <cstdint>
#include <optional>
#include <string>

struct Network { std::uint32_t address; int prefix; };

std::optional<std::uint32_t> parseIPv4(const std::string& text)
{
    std::uint32_t value{ 0 };
    int parts{ 0 };
    std::size_t at{ 0 };
    while (parts < 4)
    {
        std::size_t digits{ 0 };
        unsigned part{ 0 };
        while (at < text.size() && std::isdigit(static_cast<unsigned char>(text[at])) && digits < 4)
        {
            part = part * 10 + static_cast<unsigned>(text[at] - '0');
            ++at;
            ++digits;
        }
        if (digits == 0 || digits > 3 || part > 255) return std::nullopt;
        value = (value << 8) | part;
        ++parts;
        if (parts < 4)
        {
            if (at >= text.size() || text[at] != '.') return std::nullopt;
            ++at;
        }
    }
    if (at != text.size()) return std::nullopt;
    return value;
}

std::string formatIPv4(std::uint32_t a)
{
    return std::to_string(a >> 24) + "." + std::to_string((a >> 16) & 0xFF) + "." + std::to_string((a >> 8) & 0xFF) + "." + std::to_string(a & 0xFF);
}

std::uint32_t maskOf(int prefix)
{
    return prefix <= 0 ? 0u : prefix >= 32 ? 0xFFFFFFFFu : ~((1u << (32 - prefix)) - 1u);
}

std::optional<Network> parseCidr(const std::string& text)
{
    const std::size_t slash{ text.find('/') };
    if (slash == std::string::npos) return std::nullopt;
    const auto address{ parseIPv4(text.substr(0, slash)) };
    const std::string p{ text.substr(slash + 1) };
    if (!address || p.empty() || p.size() > 2) return std::nullopt;
    for (char c : p) if (!std::isdigit(static_cast<unsigned char>(c))) return std::nullopt;
    const int prefix{ std::stoi(p) };
    if (prefix > 32) return std::nullopt;
    return Network{ *address & maskOf(prefix), prefix };
}

bool contains(const Network& n, std::uint32_t address) { return (address & maskOf(n.prefix)) == n.address; }
std::uint32_t broadcastOf(const Network& n) { return n.address | ~maskOf(n.prefix); }

std::uint64_t usableHosts(int prefix)
{
    if (prefix >= 32) return 1;
    if (prefix == 31) return 2;
    return (std::uint64_t{ 1 } << (32 - prefix)) - 2;
}

bool isPrivate(std::uint32_t a)
{
    return (a & 0xFF000000u) == 0x0A000000u || (a & 0xFFF00000u) == 0xAC100000u || (a & 0xFFFF0000u) == 0xC0A80000u;
}

unitTests:
TEST("parsing and formatting") {
    CHECK_EQ(parseIPv4("192.168.1.20").value_or(0), 0xC0A80114u);
    CHECK_EQ(parseIPv4("0.0.0.0").value_or(1), 0u);
    CHECK_EQ(parseIPv4("255.255.255.255").value_or(0), 0xFFFFFFFFu);
    for (const char* bad : { "256.1.1.1", "1.2.3", "1.2.3.4.5", "1..3.4", "a.b.c.d", "1.2.3.4 ", "0001.2.3.4", "" })
        CHECK(!parseIPv4(bad).has_value());
    CHECK_EQ(formatIPv4(0xC0A80114u), std::string("192.168.1.20"));
}
TEST("CIDR and masks") {
    CHECK_EQ(maskOf(24), 0xFFFFFF00u);
    CHECK_EQ(maskOf(20), 0xFFFFF000u);
    CHECK_EQ(maskOf(0), 0u);
    CHECK_EQ(maskOf(32), 0xFFFFFFFFu);
    const auto n{ parseCidr("10.20.30.40/20") };
    CHECK(n.has_value());
    if (n) { CHECK_EQ(formatIPv4(n->address), std::string("10.20.16.0")); CHECK_EQ(n->prefix, 20); }
    CHECK(!parseCidr("10.0.0.0/33").has_value());
    CHECK(!parseCidr("10.0.0.0").has_value());
    CHECK(!parseCidr("10.0.0.0/").has_value());
}
TEST("membership and broadcast") {
    const Network n{ *parseCidr("192.168.1.0/24") };
    CHECK(contains(n, *parseIPv4("192.168.1.77")));
    CHECK(!contains(n, *parseIPv4("192.168.2.1")));
    CHECK_EQ(formatIPv4(broadcastOf(n)), std::string("192.168.1.255"));
    const Network all{ *parseCidr("0.0.0.0/0") };
    CHECK(contains(all, *parseIPv4("8.8.8.8")));
}
TEST("hosts and private ranges") {
    CHECK_EQ(usableHosts(24), 254u);
    CHECK_EQ(usableHosts(26), 62u);
    CHECK_EQ(usableHosts(31), 2u);
    CHECK_EQ(usableHosts(32), 1u);
    CHECK_EQ(usableHosts(0), 4294967294ull);
    CHECK(isPrivate(*parseIPv4("10.1.2.3")));
    CHECK(isPrivate(*parseIPv4("172.31.255.1")));
    CHECK(!isPrivate(*parseIPv4("172.32.0.1")));
    CHECK(isPrivate(*parseIPv4("192.168.0.1")));
    CHECK(!isPrivate(*parseIPv4("8.8.8.8")));
}

